import argparse, html, json
p=argparse.ArgumentParser();p.add_argument('directory');a=p.parse_args();root=Path(a.directory);root.mkdir(parents=True,exist_ok=True)
def video(scene,key,title,note,path=None):
 base=path or f'{scene}/{key}'
 return f'<figure><figcaption><b>{title}</b><small>{note}</small></figcaption><video controls muted playsinline preload="metadata" src="{base}.mp4" poster="{base}_poster.jpg"></video><a href="{base}.mp4">单独打开视频 ↗</a></figure>'
def group(scene,start,cards):
 return f'<div class="syncgroup" data-start="{start}"><div class="controls"><button data-act="play">同步播放</button><button data-act="pause">暂停</button><button data-act="prev">上一帧</button><button data-act="next">下一帧</button><select aria-label="播放速度"><option value="1">1×</option><option value="0.5">0.5×</option></select><output>f{start} · 0.0s</output><input type="range" min="0" max="29" step="1" value="0" aria-label="逐帧时间轴"></div><div class="grid">'+''.join(video(scene,*c) for c in cards)+'</div></div>'
