  group(scene,start,[('r4_condition','r4模型所见遮挡','整块矩形会遮住车间结构；这不是最终写回范围。'),('r6_condition','r6模型所见遮挡','逐车矩形，并用GT投影约束SAM离群像素。'),('r6_prior','r6内部prior','0255草地更可辨，但最终扩散仍会改坏。')]),
