parts+=['<section id="controls"><h2>相同语义guard的逐帧结果</h2><p>检测原车的正控制均为30/30。下表是“触发新车辆告警的帧数”，越小只表示告警更少；灰色马赛克、接缝和错误杆件可能完全不触发它。</p><table><tr><th>配置</th><th>0230</th><th>0255</th><th>观察与结论</th></tr>',
 '<tr><td>r2 旧Hybrid</td><td>21/30</td><td>30/30</td><td>灰块和车辆再生</td></tr><tr><td>r3 连贯矩形条件</td><td>14/30</td><td>29/30</td><td>0230早段改善，后段与0255仍失败</td></tr><tr><td>r3-noise</td><td>14/30</td><td>27/30</td><td>抹去局部prior初值不足以解决</td></tr><tr><td>r4 整块车列遮挡</td><td>2/30</td><td>0/30</td><td>有结构破坏；零检测也拒绝</td></tr><tr><td>r5 无车prior+局部条件</td><td>15/30</td><td>24/30</td><td>车形回归，不采用</td></tr><tr><td>r6 逐车条件遮挡</td><td>1/30</td><td>3/30</td><td>车形显著减少，杆件/色块/接缝仍失败</td></tr></table>',
 '<p>所有候选的指定protect与写回范围外像素变化均为0。独立检测到的邻车mask仍有约541/1,279,616、4,519–4,520/861,732像素改变，因此没有声称“所有邻车绝对不变”。r3改变了形状、范围与保护孔洞处理；r4/r6改变了条件上下文，不能把差异都归因于某个单一像素膨胀量。</p>',
 '<h3>边界与复核</h3><p>这两例已反复用于开发，不能当独立测试。GT相机/框、助手选取场景侧和围栏提示均已使用；不是纯RGB全自动。传播阶段填上18.1%/29.8%的模型孔洞不等于真实证据覆盖，原先严格接受的证据仍极少。隐藏区域没有可靠完整GT，未宣称恢复了真实世界。</p><p>任务继续集中在失败段；旧DriveEditor默认、原GLB、Ω及全部失败均保留，人工 verdict 为null。</p><p><a href="video_validation.json">远端视频实际解码</a> · <a href="review_validation.json">本地静态与解码检查</a> · <a href="summary.json">分阶段证据摘要</a></p></section>']
js='''const groups=[...document.querySelectorAll('.syncgroup')];for(const g of groups){const vs=[...g.querySelectorAll('video')],r=g.querySelector('input'),o=g.querySelector('output'),start=Number(g.dataset.start);let seeking=false;const label=()=>{const f=Math.min(29,Math.round(vs[0].currentTime*10));r.value=f;o.textContent=`f${start+f} · ${(f/10).toFixed(1)}s`};const seek=f=>{seeking=true;vs.forEach(v=>{v.pause();v.currentTime=Math.max(0,Math.min(29,f))/10});seeking=false;label()};g.querySelectorAll('button').forEach(b=>b.addEventListener('click',async()=>{const a=b.dataset.act;if(a==='play'){for(const other of groups)if(other!==g)other.querySelectorAll('video').forEach(v=>v.pause());const t=vs[0].currentTime>=2.9?0:vs[0].currentTime;vs.forEach(v=>v.currentTime=t);await Promise.allSettled(vs.map(v=>v.play()))}else if(a==='pause')vs.forEach(v=>v.pause());else seek(Number(r.value)+(a==='next'?1:-1))}));r.addEventListener('input',()=>seek(Number(r.value)));g.querySelector('select').addEventListener('change',e=>vs.forEach(v=>v.playbackRate=Number(e.target.value)));vs[0].addEventListener('timeupdate',()=>{label();if(!seeking&&!vs[0].paused)for(const v of vs.slice(1))if(Math.abs(v.currentTime-vs[0].currentTime)>.13)v.currentTime=vs[0].currentTime});vs[0].addEventListener('ended',()=>vs.forEach(v=>v.pause()))}'''
parts+=['<footer>视频逐帧实际解码、引用与JS语法检查；没有宣称浏览器交互已测试。原始PNG与日志位于远端任务目录。MP4为审核压缩版，像素合同以PNG为准。</footer>',f'<script>{js}</script></main></body></html>']
(root/'index.html').write_text('\n'.join(parts),encoding='utf-8',newline='\n')
print(root/'index.html')
